      SUBROUTINE FRING3CC     CALCULATES THIRD-ORDER FRINGE FIELD TRANSFER MATRIXC      INCLUDE 'ELM2A.CIN'      INCLUDE 'ELM2B.CIN'      INCLUDE 'ELM4A.CIN'      INCLUDE 'U.CIN'CC     LOCAL VARIABLESC      REAL           BEE, EPS      REAL           FINT1, FINTJ1, FINTJ2, FINTJ3, FINTJ4      REAL           SB2, SB3, SB4, TB2, TB3, TB4      EQUIVALENCE    (LAYL,FINT1)C------------------------------------------------------------------------------      EPS = 2.0*H0*APB(2)      TB2 = TB*TB      TB3 = TB2*TB      TB4 = TB3*TB      SB2 = SB*SB      SB3 = SB2*SB      SB4 = SB3*SB      BEE = 6.0*FINT1      FINTJ1 = 1.0/BEE      FINTJ2 = 0.0      FINTJ3 = 1.0/6.0      FINTJ4 = 0.0      IF (.NOT. BEFORE) GO TO 10CC     ENTRANCE FACEC      U(1,1) = - 0.5*H0*RABT*TB*SB3      U(1,2) = - H0*TB3      U(1,8) = - 0.5*H0**2*TB2*(SB2 + TB2) + 1.5*H0*RABT*TB*SB3      U(1,9) = H0*TB*SB2      U(1,14) = H0*TB*(SB2 + TB2)      U(1,36) = 0.5*H0*TB2      U(1,41) = - 0.5*H0*SB2C      U(2,1) = 0.5*H0**3*TB3 + 0.5*H0*RABT**2*TB*SB4      U(2,2) = 1.5*H0**2*TB2 + 1.5*H0*RABT*TB*SB3      U(2,3) = 0.5*H0*TB*(2.0*SB2 + 1.0)      U(2,8) = 0.5*H0**3*TB3     1       + 0.5*H0**2*RABT*(SB2 + 5.0*TB2)*SB3     2       - 1.5*H0*RABT**2*TB*SB4      U(2,9) = 3.0*H0**2*TB2*SB2 - 1.5*H0*RABT*TB*SB3      U(2,14) = 2.0*H0**2*TB4 - 3.0*H0*RABT*TB*SB3      U(2,15) = - 2.0*H0*TB*SB2      U(2,17) = 0.5*H0*TB*(SB2 - 3.0*TB2)      U(2,36) = - 0.5*H0*RABT*SB3      U(2,37) = - H0*TB2      U(2,41) = - H0**2*TB*(SB2 + TB2) + 0.5*H0*RABT*SB3      U(2,44) = H0*TB2      U(2,51) = H0*TBC      U(3,5) = 1.5*H0*RABT*TB*SB3      U(3,6) = H0*TB*(SB2 + TB2)      U(3,10) = H0**2*(2.0*(SB2 + TB2)*SB2*FINTJ2/3.0     1        + (SB2 + 5.0*TB2)*SB2/6.0)     2        - 0.5*H0*RABT*TB*SB3      U(3,11) = H0*TB3      U(3,16) = - H0*SB2*TB      U(3,39) = - H0*TB2C      U(4,5) = - 0.5*H0**3*TB3 - 1.5*H0*RABT**2*TB*SB4      U(4,6) = - H0**2*TB2 - 3.0*H0*RABT*TB*SB3      U(4,7) = - 0.5*H0*TB*(1.0 + 2.0*SB2)      U(4,10) = H0**3*( - 2.0*(SB2 + TB2)*SB*FINTJ1/(3.0*EPS)     1        + TB*(8.0*SB4 - 5.0*SB2*TB2 + 9.0*TB4)/18.0     2        + 2.0*TB*(9.0*SB2 + 5.0*TB2)*SB2*FINTJ4/3.0     3        - 2.0*TB*SB2*(SB2 + TB2)*FINTJ2/3.0)     4        - H0**2*RABT*(SB3*(SB2 + 5.0*TB2)/6.0     5        - 2.0*SB*(5.0*SB2 + TB2)*FINTJ2/3.0)     6        + 0.5*H0*RABT**2*TB*SB4      U(4,11) = 0.5*H0**2*TB2 - 1.5*H0*RABT*TB*SB3      U(4,12) = - 2.0*H0*TB3      U(4,16) = H0**2*(- 0.5*(1.0 + 2.0*TB4)     1        - 2.0*SB2*(SB2 + TB2)*FINTJ2)     2        + 1.5*H0*RABT*TB*SB3      U(4,19) = H0*(TB3 - 0.5*TB)      U(4,39) = H0*RABT*SB3      U(4,40) = H0*SB2      U(4,42) = H0*TB2      U(4,53) = - H0*TB      GO TO 100CC     EXIT FACEC   10 U(1,1) = - 0.5*H0**2*TB4 + 0.5*H0*RABT*TB*SB3      U(1,2) = - H0*TB3      U(1,8) = 0.5*H0**2*TB2*(1.0 + SB2) - 1.5*H0*RABT*TB*SB3      U(1,9) = H0*TB*SB2      U(1,14) = H0*TB*(SB2 + TB2)      U(1,36) = - 0.5*H0*TB2      U(1,41) = 0.5*H0*SB2C      U(2,1) = 0.5*H0**3*TB3*SB2     1       - H0**2*RABT*TB2*SB3 + 0.5*H0*RABT**2*TB*SB4      U(2,2) = 1.5*H0**2*TB2*SB2 - 1.5*H0*RABT*TB*SB3      U(2,3) = 0.5*H0*TB*(1.0 + 2.0*SB2)      U(2,8) = 1.5*H0**3*TB3*SB2 - 1.5*H0*RABT**2*TB*SB4      U(2,9) = 1.5*H0**2*TB2*SB2 + 1.5*H0*RABT*TB*SB3      U(2,14) = - H0**2*TB2*(1.0 + SB2) + 3.0*H0*RABT*TB*SB3      U(2,15) = - 2.0*H0*TB*SB2      U(2,17) = 0.5*H0*TB*(SB2 - 3.0*TB2)      U(2,36) = H0**2*TB3 - 0.5*H0*RABT*SB3      U(2,37) = H0*TB2      U(2,41) = H0**2*TB3 + 0.5*H0*RABT*SB3      U(2,44) = - H0*TB2      U(2,51) = H0*TBC      U(3,5) = 0.5*H0**2*TB2*(2.0*SB2 + TB2) - 1.5*H0*RABT*TB*SB3      U(3,6) = H0*TB*(SB2 + TB2)      U(3,10) = - H0**2*(2.0*(SB2 + TB2)*SB2*FINTJ2/3.0     1        + (SB2 - 4.0*TB2)*SB2/6.0)     2        + 0.5*H0*RABT*TB*SB3      U(3,11) = H0*TB3      U(3,16) = - H0*SB2*TB      U(3,39) = H0*TB2C      U(4,5) = - 0.5*H0**3*TB3*(1.0 + 3.0*SB2)     1       + 0.5*H0**2*RABT*SB3*(SB2 + 5.0*TB2)     2       - 1.5*H0*RABT**2*TB*SB4      U(4,6) = - H0**2*TB2*(1.0 + 3.0*SB2) + 3.0*H0*RABT*TB*SB3      U(4,7) = - 0.5*H0*TB*(1.0 + 2.0*SB2)      U(4,10) = H0**3*( - 2.0*(SB2 + TB2)*SB*FINTJ1/(3.0*EPS)     1        + TB*(2.0*SB4 - 8.0*SB2*TB2 + 9.0*TB4)/18.0     2        + 2.0*TB*(9.0*SB2 + 5.0*TB2)*SB2*FINTJ4/3.0     3        - 2.0*TB*(SB2 + TB2)*SB2*FINTJ2/3.0)     4        - H0**2*RABT*(SB3/6.0     5        + 2.0*TB2*SB*(5.0*SB2 + TB2)*FINTJ2/3.0)     6        + 0.5*H0*RABT**2*TB*SB4      U(4,11) = - 0.5*H0**2*TB2*(SB2 + 2.0*TB2) + 1.5*H0*RABT*TB*SB3      U(4,12) = - 2.0*H0*TB3      U(4,16) = H0**2*(0.5*(1.0 + 5.0*TB2 + TB4)     1        + 2.0*SB2*(SB2 + TB2)*FINTJ2)     2        - 1.5*H0*RABT*TB*SB3      U(4,19) = H0*(TB3 - 0.5*TB)      U(4,39) = - 2.0*H0**2*SB2*TB + H0*RABT*SB3      U(4,40) = - H0*SB2      U(4,42) = - H0*TB2      U(4,53) = - H0*TBC  100 RETURN      END